  const youtubeChannelSnapshots=youtubeAnalyticsSnapshots.filter(snapshot=>snapshot.subjectType==="CHANNEL");
  const youtubeVideoSnapshots=youtubeAnalyticsSnapshots.filter(snapshot=>snapshot.subjectType==="VIDEO").slice(0,20);



  const metaAnalyticsSnapshots=metaAccounts.length?await db.metaAnalyticsSnapshot.findMany({where:{workspaceId:workspace.id,socialAccountId:{in:metaAccounts.map(account=>account.id)}},orderBy:{fetchedAt:"desc"},distinct:["socialAccountId","subjectType","subjectId"],take:100,select:{id:true,socialAccountId:true,subjectType:true,subjectId:true,reportDate:true,fetchedAt:true,metrics:true}}):[];
  const metaAccountSnapshots=metaAnalyticsSnapshots.filter(snapshot=>snapshot.subjectType==="ACCOUNT");
  const metaMediaSnapshots=metaAnalyticsSnapshots.filter(snapshot=>snapshot.subjectType==="MEDIA").slice(0,20);

  const pinterestAnalyticsSnapshots=pinterestAccounts.length?await db.pinterestAnalyticsSnapshot.findMany({where:{workspaceId:workspace.id,socialAccountId:{in:pinterestAccounts.map(account=>account.id)}},orderBy:{fetchedAt:"desc"},distinct:["socialAccountId"],select:{id:true,socialAccountId:true,startDate:true,endDate:true,fetchedAt:true,metrics:true}}):[];
  const pinterestReadableAccounts=pinterestAccounts.filter(account=>account.scopes.includes("pins:read"));
  const pinterestPublishedTargets=pinterestReadableAccounts.length?await db.socialPostTarget.findMany({
    where:{workspaceId:workspace.id,provider:"PINTEREST",status:"PUBLISHED",providerPostId:{not:null},socialAccountId:{in:pinterestReadableAccounts.map(account=>account.id)}},
    orderBy:{publishedAt:"desc"},take:20,
    select:{id:true,providerPostId:true,publishedAt:true,uploadMetadata:true,contentPost:{select:{title:true,body:true}},socialAccount:{select:{id:true,accountName:true,brandId:true}}},
  }):[];
  const pinterestPinSnapshots=pinterestPublishedTargets.length?await db.pinterestPinAnalyticsSnapshot.findMany({
    where:{workspaceId:workspace.id,targetId:{in:pinterestPublishedTargets.map(target=>target.id)}},
    orderBy:{fetchedAt:"desc"},distinct:["targetId"],
    select:{id:true,targetId:true,pinId:true,startDate:true,endDate:true,fetchedAt:true,metrics:true},
  }):[];
  const crossPlatformTargets=await db.socialPostTarget.findMany({
    where:{workspaceId:workspace.id,status:"PUBLISHED",publishedAt:{gte:new Date(Date.now()-90*86400000)},provider:{in:["FACEBOOK","INSTAGRAM","TIKTOK","YOUTUBE","LINKEDIN","PINTEREST"]}},
    orderBy:{publishedAt:"desc"},take:500,
    select:{id:true,provider:true,publishedAt:true,providerPostId:true,socialAccount:{select:{id:true,accountName:true,brandId:true}}}
  });
  const crossPlatformPinterestIds=crossPlatformTargets.filter(target=>target.provider==="PINTEREST").map(target=>target.id);
  const crossPlatformPinterestSnapshots=crossPlatformPinterestIds.length?await db.pinterestPinAnalyticsSnapshot.findMany({where:{workspaceId:workspace.id,targetId:{in:crossPlatformPinterestIds}},orderBy:{fetchedAt:"desc"},distinct:["targetId"],select:{targetId:true,fetchedAt:true,metrics:true}}):[];
  const crossPlatformPinterestByTarget=new Map(crossPlatformPinterestSnapshots.map(snapshot=>[snapshot.targetId,snapshot]));
  const crossPlatformProviders=["FACEBOOK","INSTAGRAM","PINTEREST","LINKEDIN","TIKTOK","YOUTUBE"] as const;
